    not_approved_elements = page.get_by_role('cell', name='Not Approved')
    count = await not_approved_elements.count()
    if count > 0:
        # If found, get the text content of the first matching element
        not_approved_text = await not_approved_elements.first.text_content()
        # Extract numeric count from the text, assuming it contains the number
        import re
        match = re.search(r'\d+', not_approved_text)
        if match:
            return match.group()
        else:
            return not_approved_text
    else:
        # If not found, try other roles or names
        not_approved_elements = page.get_by_role('row', name='Not Approved')
        count = await not_approved_elements.count()
        if count > 0:
            not_approved_text = await not_approved_elements.first.text_content()
            import re
            match = re.search(r'\d+', not_approved_text)
            if match:
                return match.group()
            else:
                return not_approved_text
        else:
            # Fallback: search for any element with 'Not Approved' in name
